<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Page extends Model{protected $fillable=['parent_id','title','slug','section','template','stl_model','stl_rot_x','stl_rot_y','stl_rot_z','stl_zoom','stl_color','excerpt','content','meta_title','meta_description','sort','is_published'];protected $casts=['is_published'=>'boolean'];public function parent(){return $this->belongsTo(self::class,'parent_id');}public function children(){return $this->hasMany(self::class,'parent_id')->orderBy('sort');}public function menuItems(){return $this->hasMany(MenuItem::class);}public function media(){return $this->belongsToMany(Media::class,'page_media')->withPivot('sort')->orderByPivot('sort');}}